"""ORD_LINE renumbering migration."""

from decimal import Decimal
from typing import Any


def _string_value(value: Any) -> str:
    """Apply legacy missing/blank string semantics."""
    return "" if value is None else str(value)


def _numeric_line_no(value: Any) -> Decimal:
    """Coerce LINE_NO for numeric ordering; blank compares as zero."""
    if value is None:
        return Decimal(0)

    text = str(value).strip()
    if text == "":
        return Decimal(0)

    return Decimal(text)


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and contiguously renumber lines per order."""
    surviving: list[tuple[str, Decimal, int, dict]] = []

    for position, row in enumerate(lines):
        if _string_value(row.get("DEL_FLG", "")) == "Y":
            continue

        order_id = _string_value(row.get("ORD_ID", ""))
        line_no = _numeric_line_no(row.get("LINE_NO", ""))
        surviving.append((order_id, line_no, position, row))

    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order: str | None = None
    new_line_no = 0

    for order_id, _, _, source_row in surviving:
        if order_id != current_order:
            current_order = order_id
            new_line_no = 1
        else:
            new_line_no += 1

        migrated_row = dict(source_row)
        migrated_row["LINE_NO"] = new_line_no
        result.append(migrated_row)

    return result
